// Frozen reference point for mcp:policy-eval.
//
// The policy text and category definitions live in policy-baseline.json and are
// regenerated by `bun run mcp:rebaseline`. The routing algorithm below is a frozen
// copy of selectRelevantCategoryIds from routing.ts at the same commit, so that a
// change to either the policy text or the routing logic shows up as a measured
// delta instead of moving silently with the code under test.
import { readFile } from "node:fs/promises";

const snapshot = JSON.parse(await readFile(new URL("./policy-baseline.json", import.meta.url), "utf8"));

export const baselineCommit = snapshot.commit;
export const baselineCapturedAt = snapshot.capturedAt;
export const baselineCategoryDefinitions = snapshot.categoryDefinitions;
export const baselinePolicies = snapshot.policies;

const MAX_RELEVANT_CATEGORIES = 6;
const baselineIds = ["global", "communication", "unslop", "code-style"];
const baselineIdSet = new Set(baselineIds);
const taskModeIds = new Set(["debugging", "research", "code-review"]);
const domainIds = new Set(["dotnet", "csharp-style", "sql"]);

export function selectBaselineCategoryIds(input) {
  const requested = new Set(input.categories ?? []);
  if (requested.size > 0) {
    return includeBaseline(
      baselineCategoryDefinitions.map(({ id }) => id).filter((id) => requested.has(id))
    );
  }

  const text = [input.task, input.language, input.framework].filter(Boolean).join(" ");
  const matchedBaseline = baselineCategoryDefinitions
    .filter(({ id }) => baselineIdSet.has(id))
    .some(({ keywords }) => keywords.some((keyword) => matchesKeyword(text, keyword)));
  const selected = baselineCategoryDefinitions
    .filter(({ id }) => !baselineIdSet.has(id))
    .map((category, index) => ({
      id: category.id,
      index,
      score: category.keywords.filter((keyword) => matchesKeyword(text, keyword)).length,
    }))
    .filter(({ score }) => score > 0)
    .sort(
      (left, right) =>
        routingPriority(right.id) - routingPriority(left.id) ||
        right.score - left.score ||
        left.index - right.index
    )
    .slice(0, MAX_RELEVANT_CATEGORIES)
    .map(({ id }) => id);

  return includeBaseline(selected.length > 0 ? selected : matchedBaseline ? [] : ["engineering"]);
}

function routingPriority(id) {
  if (taskModeIds.has(id)) return 2;
  if (domainIds.has(id)) return 1;
  return 0;
}

function includeBaseline(selected) {
  const next = [...selected];
  const ids = new Set(next);

  for (const id of [...baselineIds].reverse()) {
    if (!ids.has(id)) next.unshift(id);
  }

  return next;
}

function matchesKeyword(text, keyword) {
  const phrase = keyword
    .trim()
    .split(/\s+/)
    .map((part) => part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
    .join("\\s+");

  return new RegExp(`(?<![a-z0-9])${phrase}(?![a-z0-9])`, "i").test(text);
}
